'use client'

import React, { useState, useEffect } from 'react'
import { cn } from '@/lib/utils'
import { CommunityWallCard, type CommunityMessage } from './community-wall-card'
import { InfiniteCanvas } from './infinite-canvas'
import { LeaveNoteDialog } from './leave-note-dialog'
import { Button } from '@/components/spaceui/button-squircle'
import { StatusBadge } from '@/components/spaceui/status-badge'
export { CommunityWallCard, type CommunityMessage } from './community-wall-card'
export { InfiniteCanvas } from './infinite-canvas'
export { LeaveNoteDialog } from './leave-note-dialog'
export { patterns } from './patterns'

export interface CommunityWallProps {
  messages?: CommunityMessage[]
  onAddNote?: (note: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => Promise<boolean | void>
  className?: string
  height?: string | number
  user?: any
  open?: boolean
  onOpenChange?: (open: boolean) => void
  showFloatingButton?: boolean
  avatarSource?: 'user' | 'spaceui' | 'auto'
}

export function CommunityWall({
  messages: externalMessages,
  onAddNote,
  className,
  height,
  user,
  open: controlledOpen,
  onOpenChange: setControlledOpen,
  showFloatingButton = true,
  avatarSource = 'auto',
}: CommunityWallProps) {
  const [messages, setMessages] = useState<CommunityMessage[]>(externalMessages ?? [])
  const [internalOpen, setInternalOpen] = useState(false)
  const open = controlledOpen !== undefined ? controlledOpen : internalOpen
  const setOpen = setControlledOpen || setInternalOpen

  useEffect(() => {
    if (externalMessages !== undefined) {
      setMessages(externalMessages)
    }
  }, [externalMessages])

  const handleAddNote = async (newNote: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => {
    if (onAddNote) {
      const success = await onAddNote(newNote)
      if (success === false) return false
    }

    const created: CommunityMessage = {
      id: 'local-' + Date.now(),
      creator_name: newNote.creator_name,
      message: newNote.message,
      patternIndex: newNote.pattern_index,
      pattern_index: newNote.pattern_index,
      rotation: newNote.rotation,
      creator_avatar_url: newNote.creator_avatar_url,
      created_at: new Date().toISOString(),
    }
    setMessages((prev) => [created, ...prev])
    return true
  }

  return (
    <div
      style={height ? { height: typeof height === 'number' ? `${height}px` : height } : undefined}
      className={cn('relative size-full', className)}
    >
      {/* Floating Leave Note Trigger Button */}
      {showFloatingButton && (
        <div className="absolute top-4 left-4 z-20">
          <Button
            variant="default"
            size="lg"
            hover
            whileTap
            onClick={() => setOpen(true)}
            pointer
            className="flex items-center px-6 py-4"
          >
            <div className="relative">
              <StatusBadge
                status={user ? 'online' : 'busy'}
                showIndicator
                animated
                size="sm"
                className="bg-inherit [&_div]:squircle! [&_div]:rounded-7xl! p-0"
              />
            </div>
            <span className="text-sm font-medium">Leave a Note</span>
          </Button>
        </div>
      )}

      {/* Mobile: Grid layout */}
      <div className="size-full block md:hidden overflow-y-auto pt-16">
        <div className="flex flex-wrap justify-center gap-8 p-6 pb-24">
          {messages.map((msg) => (
            <CommunityWallCard
              key={msg.id}
              message={msg.message}
              patternIndex={msg.patternIndex ?? msg.pattern_index ?? 0}
              author={msg.creator_name || msg.author}
              profilePicture={msg.creator_avatar_url || msg.profilePicture}
              rotation={msg.rotation}
              avatarSource={avatarSource}
              className="h-75 w-63"
            />
          ))}
        </div>
      </div>

      {/* Desktop: Infinite canvas */}
      <div className="size-full hidden md:block">
        <InfiniteCanvas messages={messages} avatarSource={avatarSource} />
      </div>

      {/* Exact CommentForm Modal */}
      <LeaveNoteDialog
        open={open}
        onOpenChange={setOpen}
        user={user}
        avatarSource={avatarSource}
        onSubmitNote={handleAddNote}
      />
    </div>
  )
}

'use client'

import React, { useMemo } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/ui/card'
import { Avatar as SpaceAvatar } from '@usespaceui/avatars/react'
import { Squishmoji } from '@usespaceui/squishmoji/react'
import { patterns } from './patterns'

export interface CommunityMessage {
  id: string
  creator_name?: string
  author?: string
  creator_avatar_url?: string | null
  profilePicture?: string | null
  message: string
  pattern_index?: number
  patternIndex?: number
  rotation?: number
  is_verified?: boolean
  created_at?: string
}

export interface CommunityWallCardProps {
  patternIndex?: number
  message?: string
  rotation?: number
  author?: string
  profilePicture?: string | null
  className?: string
  avatarSource?: 'user' | 'spaceui' | 'auto'
}

export function CommunityWallCard({
  patternIndex = 0,
  message = '',
  rotation = 0,
  author = '',
  profilePicture = '',
  className = '',
  avatarSource = 'auto',
}: CommunityWallCardProps) {
  const pattern = patterns[patternIndex % patterns.length]

  const isSquishmoji = useMemo(() => {
    const seed = author || message || 'guest'
    let hash = 0
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i)
      hash |= 0
    }
    return Math.abs(hash) % 2 === 0
  }, [author, message])

  const showUserAvatar = (avatarSource === 'user' || avatarSource === 'auto') && Boolean(profilePicture)

  const avatarNode = useMemo(() => {
    if (showUserAvatar) {
      return <img src={profilePicture!} alt={author || 'Avatar'} className="size-full object-cover" loading="lazy" />
    }
    if (isSquishmoji) {
      return (
        <span className="flex size-full origin-center [&>span]:scnale-[1.55] items-center justify-center">
          <Squishmoji
            seed={author || 'Guest'}
            size={30}
            animate={false}
            shape="all"
            expression="all"
            backgroundStyle="all"
          />
        </span>
      )
    }
    return (
      <span className="flex size-full origin-center items-center justify-center">
        <SpaceAvatar name={author || 'Guest'} variant="all" size={30} />
      </span>
    )
  }, [showUserAvatar, profilePicture, author, isSquishmoji])

  return (
    <Card
      className={cn(
        'bg-card rounded-3xl border-2 border-muted cursor-pointer transition-[border-color,box-shadow] duration-200 group transform-gpu will-change-transform pointer-events-none',
        className,
      )}
      style={{ transform: `rotate(${rotation}deg)` }}
    >
      <CardContent className="flex flex-col items-start justify-between p-0 gap-3 h-full">
        <div className="relative size-full flex flex-col items-center gap-2 rounded-2xl bg-muted p-2 overflow-hidden">
          <div className="relative size-full flex flex-row items-center justify-center p-4 min-h-50 rounded-2xl bg-card overflow-hidden">
            {pattern?.content}
            <p className="w-full z-10 line-clamp-6 text-center text-xl font-bold text-foreground whitespace-pre-line wrap-break-word">
              {message}
            </p>
          </div>
          <div className="flex w-full items-center gap-2">
            <div className="size-8 shrink-0 overflow-hidden squircle rounded-full bg-background border-2 border-muted flex items-center justify-center">
              {avatarNode}
            </div>
            <p className="truncate text-muted-foreground text-sm font-medium">{author || 'Anonymous'}</p>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

'use client'

import React, { useState, useRef, useMemo, useEffect, type ReactNode } from 'react'
import { useMotionValue } from 'motion/react'
import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/ui/card'
import { CommunityWallCard, type CommunityMessage } from './community-wall-card'
import { Button } from '@/components/spaceui/button-squircle'
import { IconCurrentLocationFilled } from '@tabler/icons-react'
import { ProximityGrid } from '@/components/blocks/interactive-grid-hero/interactive-grid-hero-1/proximity-grid'

interface Position {
  x: number
  y: number
}

interface BoundingBox {
  x: number
  y: number
  width: number
  height: number
}

interface InfiniteCanvasProps {
  messages: CommunityMessage[]
  children?: ReactNode
  className?: string
  avatarSource?: 'user' | 'spaceui' | 'auto'
}

// Card dimensions for collision detection
const CARD_WIDTH = 260
const CARD_HEIGHT = 300
const CARD_PADDING = 40 // Minimum space between cards

// Pseudo-random number generator with seed
function seededRandom(seed: string): number {
  let hash = 0
  for (let i = 0; i < seed.length; i++) {
    hash = (hash << 5) - hash + seed.charCodeAt(i)
    hash |= 0 // Convert to 32-bit integer
  }
  const x = Math.sin(hash++) * 10000
  return x - Math.floor(x)
}

// Check if two bounding boxes overlap
function checkCollision(box1: BoundingBox, box2: BoundingBox): boolean {
  return !(
    box1.x + box1.width < box2.x ||
    box1.x > box2.x + box2.width ||
    box1.y + box1.height < box2.y ||
    box1.y > box2.y + box2.height
  )
}

// Generate consistent random position for a message using radial distribution
function generatePosition(
  messageId: string,
  totalMessages: number,
  currentIndex: number,
  existingPositions: Position[],
): Position {
  const maxAttempts = 100
  const baseRadius = 250
  const cardsPerLayer = 8
  const layerSpacing = 380
  const layerRadius = Math.floor(currentIndex / cardsPerLayer) * layerSpacing

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const angleSeed = messageId + '_angle_' + attempt
    const radiusSeed = messageId + '_radius_' + attempt

    const angle = seededRandom(angleSeed) * Math.PI * 2
    const radiusVariation = seededRandom(radiusSeed) * 200
    const radius = baseRadius + radiusVariation + layerRadius

    const x = Math.cos(angle) * radius
    const y = Math.sin(angle) * radius

    const newBox: BoundingBox = {
      x: x - CARD_WIDTH / 2,
      y: y - CARD_HEIGHT / 2,
      width: CARD_WIDTH + CARD_PADDING,
      height: CARD_HEIGHT + CARD_PADDING,
    }

    let hasCollision = false
    for (const existingPos of existingPositions) {
      const existingBox: BoundingBox = {
        x: existingPos.x - CARD_WIDTH / 2,
        y: existingPos.y - CARD_HEIGHT / 2,
        width: CARD_WIDTH + CARD_PADDING,
        height: CARD_HEIGHT + CARD_PADDING,
      }

      if (checkCollision(newBox, existingBox)) {
        hasCollision = true
        break
      }
    }

    if (!hasCollision) {
      return { x: Math.round(x), y: Math.round(y) }
    }
  }

  const fallbackAngle = seededRandom(messageId + '_fallback') * Math.PI * 2
  const fallbackRadius = baseRadius + layerRadius + layerSpacing
  const x = Math.cos(fallbackAngle) * fallbackRadius
  const y = Math.sin(fallbackAngle) * fallbackRadius

  return { x: Math.round(x), y: Math.round(y) }
}

export function InfiniteCanvas({ messages, children, className, avatarSource }: InfiniteCanvasProps) {
  const [offset, setOffset] = useState<Position>({ x: 0, y: 0 })
  const [isDragging, setIsDragging] = useState(false)
  const [isTransitioning, setIsTransitioning] = useState(false)

  const offsetRef = useRef<Position>({ x: 0, y: 0 })
  const rafRef = useRef<number | null>(null)
  const canvasAreaRef = useRef<HTMLDivElement>(null)

  const pointerX = useMotionValue(-1000)
  const pointerY = useMotionValue(-1000)
  const pointerActive = useMotionValue(0)

  offsetRef.current = offset

  useEffect(() => {
    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [])

  // Memoized message positions with collision detection
  const messagePositions = useMemo(() => {
    const positions: Position[] = []
    return messages.map((message, index) => {
      let position: Position

      if (index === messages.length - 1) {
        position = { x: 0, y: 0 }
      } else {
        position = generatePosition(message.id, messages.length, index, positions)
      }

      positions.push(position)
      return {
        ...message,
        position,
      }
    })
  }, [messages])

  // Mouse drag with global window listeners to never lose drag on leave or over cards
  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.button !== 0) return

    const startX = e.clientX
    const startY = e.clientY
    const startOffsetX = offsetRef.current.x
    const startOffsetY = offsetRef.current.y

    setIsDragging(true)

    const onMouseMove = (moveEvent: MouseEvent) => {
      const dx = moveEvent.clientX - startX
      const dy = moveEvent.clientY - startY

      if (rafRef.current) cancelAnimationFrame(rafRef.current)
      rafRef.current = requestAnimationFrame(() => {
        setOffset({
          x: Math.round(startOffsetX + dx),
          y: Math.round(startOffsetY + dy),
        })
        rafRef.current = null
      })

      // Continuous proximity tracking even during drag
      const rect = canvasAreaRef.current?.getBoundingClientRect()
      if (rect) {
        pointerX.set(moveEvent.clientX - rect.left)
        pointerY.set(moveEvent.clientY - rect.top)
        pointerActive.set(1)
      }
    }

    const onMouseUp = (upEvent: MouseEvent) => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
      setIsDragging(false)
      window.removeEventListener('mousemove', onMouseMove)
      window.removeEventListener('mouseup', onMouseUp)

      const rect = canvasAreaRef.current?.getBoundingClientRect()
      if (rect) {
        const isInside =
          upEvent.clientX >= rect.left &&
          upEvent.clientX <= rect.right &&
          upEvent.clientY >= rect.top &&
          upEvent.clientY <= rect.bottom
        if (!isInside) {
          pointerActive.set(0)
        }
      }
    }

    window.addEventListener('mousemove', onMouseMove)
    window.addEventListener('mouseup', onMouseUp)
  }

  // Touch drag with global listeners
  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    if (e.touches.length !== 1) return
    const touch = e.touches[0]
    const startX = touch.clientX
    const startY = touch.clientY
    const startOffsetX = offsetRef.current.x
    const startOffsetY = offsetRef.current.y

    setIsDragging(true)

    const onTouchMove = (moveEvent: TouchEvent) => {
      if (moveEvent.touches.length !== 1) return
      const t = moveEvent.touches[0]
      const dx = t.clientX - startX
      const dy = t.clientY - startY

      if (rafRef.current) cancelAnimationFrame(rafRef.current)
      rafRef.current = requestAnimationFrame(() => {
        setOffset({
          x: Math.round(startOffsetX + dx),
          y: Math.round(startOffsetY + dy),
        })
        rafRef.current = null
      })

      const rect = canvasAreaRef.current?.getBoundingClientRect()
      if (rect) {
        pointerX.set(t.clientX - rect.left)
        pointerY.set(t.clientY - rect.top)
        pointerActive.set(1)
      }
    }

    const onTouchEnd = () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
      setIsDragging(false)
      pointerActive.set(0)
      window.removeEventListener('touchmove', onTouchMove)
      window.removeEventListener('touchend', onTouchEnd)
      window.removeEventListener('touchcancel', onTouchEnd)
    }

    window.addEventListener('touchmove', onTouchMove, { passive: false })
    window.addEventListener('touchend', onTouchEnd)
    window.addEventListener('touchcancel', onTouchEnd)
  }

  const handleRecenter = () => {
    setIsTransitioning(true)
    setOffset({ x: 0, y: 0 })
    setTimeout(() => {
      setIsTransitioning(false)
    }, 500)
  }

  const hasMoved = offset.x !== 0 || offset.y !== 0

  return (
    <div className={cn('relative w-full h-full min-h-125 select-none touch-none', className)}>
      <Card className="size-full bg-muted rounded-3xl border-2 border-muted flex-1 overflow-hidden">
        <CardContent className="size-full p-0">
          <ProximityGrid
            cellSize={56}
            gap={4}
            radius="rounded"
            proximity={4}
            inset={6}
            pointerX={pointerX}
            pointerY={pointerY}
            pointerActive={pointerActive}
            className="absolute inset-0 size-full min-h-0 bg-background overflow-hidden select-none"
          >
            <div
              ref={canvasAreaRef}
              className={cn(
                'absolute inset-0 overflow-hidden select-none touch-none',
                isDragging ? 'cursor-grabbing' : 'cursor-grab',
              )}
              onPointerMove={(e) => {
                const rect = canvasAreaRef.current?.getBoundingClientRect()
                if (rect) {
                  pointerX.set(e.clientX - rect.left)
                  pointerY.set(e.clientY - rect.top)
                  pointerActive.set(1)
                }
              }}
              onPointerLeave={() => {
                if (!isDragging) {
                  pointerActive.set(0)
                }
              }}
              onMouseDown={handleMouseDown}
              onTouchStart={handleTouchStart}
            >
              <div
                className="absolute inset-0 transform-gpu will-change-transform"
                style={{
                  transform: `translate3d(${offset.x}px, ${offset.y}px, 0)`,
                  transition: isTransitioning ? 'transform 0.5s cubic-bezier(0.16, 1, 0.3, 1)' : 'none',
                }}
              >
                {messagePositions.map((message) => (
                  <div
                    key={message.id}
                    className="absolute pointer-events-none select-none"
                    style={{
                      left: '50%',
                      top: '50%',
                      transform: `translate(calc(-50% + ${message.position.x}px), calc(-50% + ${message.position.y}px))`,
                    }}
                  >
                    <CommunityWallCard
                      message={message.message}
                      patternIndex={message.patternIndex ?? message.pattern_index ?? 0}
                      author={message.creator_name || message.author}
                      profilePicture={message.creator_avatar_url || message.profilePicture}
                      rotation={message.rotation}
                      avatarSource={avatarSource}
                      className="h-75 w-63 select-none pointer-events-none"
                    />
                  </div>
                ))}
              </div>

              <Button
                variant="default"
                size="icon-lg"
                onClick={handleRecenter}
                className={cn(
                  'absolute right-4 top-4 z-10 bg-[#8e8eff]! text-white border-0 transition-opacity cursor-pointer',
                  hasMoved ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none',
                )}
                aria-label="Recenter canvas"
                title="Recenter canvas"
                whileTap
                square
              >
                <IconCurrentLocationFilled className="size-5" />
              </Button>
            </div>
          </ProximityGrid>

          {children && children}
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Dialog,
  DialogBackdrop,
  DialogPortal,
  DialogViewport,
  DialogPopup,
  DialogHeader,
  DialogTitle,
  DialogClose,
} from '@/components/ui/dialog'
import { Button } from '@/components/spaceui/button-squircle'
import { Badge } from '@/components/spaceui/badge-squircle'
import { Textarea } from '@/components/ui/textarea'
import { Input } from '@/components/ui/input'
import { Slider } from '@/components/ui/slider'
import { RadioGroup, Radio } from '@/components/ui/radio-group'
import { ScrollArea } from '@/components/ui/scroll-area'
import { CommunityWallCard } from './community-wall-card'
import { patterns } from './patterns'
import { IconChevronLeft, IconChevronRight, IconX, IconUser, IconUserFilled } from '@tabler/icons-react'
import { Github, Google } from './social-icons'
import { loading, confirm, deny } from '@usespaceui/sounds'
import { createClient } from '@/integrations/supabase/client'
import { cn } from '@/lib/utils'
import { useConfirmExit } from '@/hooks/use-confirm-exit'

interface LeaveNoteDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  user?: any
  avatarSource?: 'user' | 'spaceui' | 'auto'
  onSubmitNote: (note: {
    creator_name: string
    message: string
    pattern_index: number
    rotation: number
    creator_avatar_url?: string | null
  }) => Promise<boolean | void>
}

const config = {
  maxCommentLength: 110,
  rotation: {
    startAt: -10,
    default: 0,
    endAt: 10,
    step: 1,
  },
}

export function LeaveNoteDialog({
  open,
  onOpenChange,
  user,
  avatarSource = 'auto',
  onSubmitNote,
}: LeaveNoteDialogProps) {
  const [isGuest, setIsGuest] = useState(false)
  const [patternIndex, setPatternIndex] = useState(() => Math.floor(Math.random() * patterns.length))
  const [rotation, setRotation] = useState(config.rotation.default)
  const [comment, setComment] = useState('')
  const [authorName, setAuthorName] = useState(user?.user_metadata?.name || user?.name || '')
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    if (open) {
      if (user?.user_metadata?.name || user?.name) {
        setAuthorName(user.user_metadata?.name || user.name)
      }
      if (!comment.trim()) {
        setPatternIndex(Math.floor(Math.random() * patterns.length))
        setRotation(config.rotation.default)
      }
    } else {
      setIsGuest(false)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, user])

  useConfirmExit(open && Boolean(comment.trim()), 'You have an unsent note — leaving will discard it.')

  const handlePrevPattern = () => {
    setPatternIndex((prev) => (prev - 1 + patterns.length) % patterns.length)
  }

  const handleNextPattern = () => {
    setPatternIndex((prev) => (prev + 1) % patterns.length)
  }

  const handleOAuthSignIn = (provider: 'github' | 'google') => {
    const url = new URL(`${window.location.origin}/api/auth/login`)
    url.searchParams.set('provider', provider)
    url.searchParams.set('next', window.location.pathname)
    window.location.href = url.toString()
  }

  const onSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()

    if (!comment.trim()) {
      try {
        deny()
      } catch {}
      return
    }

    if (comment.length > config.maxCommentLength) {
      try {
        deny()
      } catch {}
      return
    }

    try {
      loading()
    } catch {}
    setIsSubmitting(true)

    try {
      const res = await onSubmitNote({
        creator_name: authorName.trim() || 'Anonymous',
        message: comment.trim(),
        pattern_index: patternIndex,
        rotation: rotation,
        creator_avatar_url: user?.user_metadata?.avatar_url || user?.avatarUrl,
      })

      if (res !== false) {
        try {
          confirm()
        } catch {}
        setComment('')
        setPatternIndex(Math.floor(Math.random() * patterns.length))
        setRotation(config.rotation.default)
        onOpenChange(false)
      }
    } catch (err) {
      try {
        deny()
      } catch {}
    } finally {
      setIsSubmitting(false)
    }
  }

  const canLeaveNote = Boolean(user) || isGuest

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogPortal>
        <DialogBackdrop />
        <DialogViewport className="p-4 sm:p-6">
          {!canLeaveNote ? (
            /* Authentication selection step: 2 original OAuth buttons + 1 Guest button */
            <DialogPopup
              className="w-full max-w-md flex flex-col overflow-hidden rounded-3xl bg-popover text-popover-foreground p-6 squircle border-4 border-muted"
              showCloseButton={false}
            >
              <DialogHeader className="shrink-0 flex-row justify-between items-center p-0 pb-4 border-b border-border/40">
                <DialogTitle className="text-2xl font-bold text-start">Sign in to leave a note</DialogTitle>
                <DialogClose render={<Button size="icon-sm" className="rounded-lg" />}>
                  <IconX className="size-5" />
                </DialogClose>
              </DialogHeader>

              <div className="flex flex-col gap-6 pt-3">
                <p className="text-muted-foreground text-center">
                  Connect with your GitHub or Google account, or continue as a guest to leave a note on the community
                  wall.
                </p>

                <div className="flex flex-col gap-3">
                  <Button
                    variant="default"
                    size="lg"
                    hover
                    whileTap
                    pointer
                    className="w-full flex items-center justify-center gap-2.5 h-11"
                    onClick={() => handleOAuthSignIn('github')}
                  >
                    <Github size={20} className="shrink-0" />
                    <span>Continue with GitHub</span>
                  </Button>

                  <Button
                    variant="secondary"
                    size="lg"
                    hover
                    whileTap
                    pointer
                    className="w-full flex items-center justify-center gap-2.5 h-11"
                    onClick={() => handleOAuthSignIn('google')}
                  >
                    <Google size={20} className="shrink-0" />
                    <span>Continue with Google</span>
                  </Button>

                  <div className="relative my-2 flex items-center justify-center">
                    <div className="border-t border-border/60 w-full" />
                    <span className="bg-popover px-2 text-xs text-muted-foreground uppercase tracking-wider absolute">
                      or
                    </span>
                  </div>

                  <Button
                    variant="outline"
                    size="lg"
                    hover
                    whileTap
                    pointer
                    className="w-full flex items-center justify-center gap-2.5 h-11"
                    onClick={() => setIsGuest(true)}
                  >
                    <IconUserFilled className="size-5" />
                    <span>Continue as Guest</span>
                  </Button>
                </div>
              </div>
            </DialogPopup>
          ) : (
            /* Note creation form */
            <DialogPopup
              className="w-full max-w-3xl max-h-[90dvh] flex flex-col overflow-hidden rounded-3xl bg-popover text-popover-foreground p-6 squircle border-4 border-muted"
              showCloseButton={false}
            >
              <DialogHeader className="shrink-0 flex-row justify-between items-center p-0 pb-4 border-b border-border/40">
                <DialogTitle className="text-2xl font-bold text-start">Leave a Note</DialogTitle>
                <DialogClose render={<Button size="icon-sm" className="rounded-lg" />}>
                  <IconX className="size-5" />
                </DialogClose>
              </DialogHeader>

              <form id="leave-note-form" onSubmit={onSubmit} className="flex-1 min-h-0 flex flex-col">
                <ScrollArea className="flex-1 min-h-0 py-6 pr-2 overflow-x-hidden">
                  <div className="flex flex-col md:grid md:grid-cols-2 gap-8 items-start">
                    <div className="w-full order-1 md:order-2 flex flex-col items-center justify-center">
                      <div className="relative flex items-center justify-center w-full max-w-[340px] px-8 py-2">
                        <Button
                          variant="outline"
                          size="icon"
                          onClick={handlePrevPattern}
                          aria-label="Previous pattern"
                          className="absolute bg-background left-0 top-1/2 -translate-y-1/2 z-20"
                          pointer
                        >
                          <IconChevronLeft className="size-5" />
                        </Button>

                        <div className="relative flex items-center justify-center">
                          <CommunityWallCard
                            patternIndex={patternIndex}
                            author={authorName || 'You'}
                            profilePicture={user?.user_metadata?.avatar_url || user?.avatarUrl}
                            rotation={rotation}
                            avatarSource={avatarSource}
                            message={comment || 'Your note preview will appear here...'}
                            className="h-88 w-64 select-none"
                          />
                        </div>

                        <Button
                          variant="outline"
                          size="icon"
                          onClick={handleNextPattern}
                          aria-label="Next pattern"
                          className="absolute bg-background right-0 top-1/2 -translate-y-1/2 z-20"
                          pointer
                        >
                          <IconChevronRight className="size-5" />
                        </Button>
                      </div>
                    </div>

                    <div className="w-full order-2 md:order-1 space-y-4">
                      {!user?.user_metadata?.name && !user?.name && (
                        <div className="space-y-1.5">
                          <label className="text-sm font-medium text-foreground">Your Name</label>
                          <Input
                            placeholder="Your name or handle"
                            value={authorName}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setAuthorName(e.target.value)}
                            maxLength={40}
                          />
                        </div>
                      )}

                      <div className="space-y-1.5">
                        <div className="flex items-center justify-between">
                          <label className="text-sm font-medium text-foreground">Your Note</label>
                          <Badge variant="secondary" size="xs" squircle>
                            {comment.length} / {config.maxCommentLength}
                          </Badge>
                        </div>
                        <Textarea
                          name="comment"
                          placeholder="Write your note here..."
                          rows={6}
                          value={comment}
                          onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setComment(e.target.value)}
                          required
                          maxLength={config.maxCommentLength}
                          className="resize-none"
                        />
                      </div>

                      <div className="space-y-3 pt-1">
                        <div className="flex items-center gap-2">
                          <label className="text-sm font-medium min-w-16">Rotation</label>
                          <Slider
                            value={rotation}
                            min={config.rotation.startAt}
                            max={config.rotation.endAt}
                            step={config.rotation.step}
                            onValueChange={(value: any) => {
                              const newValue = Array.isArray(value) ? value[0] : value
                              setRotation(newValue as number)
                            }}
                            className="flex-1"
                          />
                          <Badge variant="secondary" squircle size="sm" className="w-12 justify-center">
                            {rotation}°
                          </Badge>
                        </div>

                        <div className="flex items-center gap-2">
                          <label className="text-sm font-medium min-w-16">Pattern</label>
                          <RadioGroup
                            value={patternIndex.toString()}
                            onValueChange={(value: any) => setPatternIndex(parseInt(value))}
                            className="flex gap-2 flex-1 flex-row flex-wrap"
                          >
                            {patterns.map((p, index) => (
                              <Radio
                                key={index}
                                value={index.toString()}
                                aria-label={`Pattern ${p.name || index + 1}`}
                              />
                            ))}
                          </RadioGroup>
                        </div>
                      </div>

                      <div className="hidden md:flex gap-2 pt-4 mt-auto">
                        <Button
                          variant="outline"
                          className="flex-1"
                          onClick={() => {
                            onOpenChange(false)
                          }}
                        >
                          Cancel
                        </Button>
                        <Button
                          type="submit"
                          variant="default"
                          className="flex-1"
                          disabled={!comment.trim() || isSubmitting}
                        >
                          {isSubmitting ? 'Submitting...' : 'Submit'}
                        </Button>
                      </div>
                    </div>
                  </div>
                </ScrollArea>

                <div className="flex md:hidden md:shrink-0 gap-2 pt-4 border-t border-border/40 mt-auto">
                  <Button
                    variant="outline"
                    className="flex-1"
                    onClick={() => {
                      onOpenChange(false)
                    }}
                  >
                    Cancel
                  </Button>
                  <Button type="submit" variant="default" className="flex-1" disabled={!comment.trim() || isSubmitting}>
                    {isSubmitting ? 'Submitting...' : 'Submit'}
                  </Button>
                </div>
              </form>
            </DialogPopup>
          )}
        </DialogViewport>
      </DialogPortal>
    </Dialog>
  )
}
